/** A read handle's own parts, before a kept read covers them. */
export interface ValueParts<A, V> {
  /** Load *args*; resolves once that request has settled. */
  load(args: A): Promise<void>;
  refresh(): Promise<void>;
  readonly isLoaded: Signal<boolean>;
  readonly value: Signal<V>;
  readonly isLoading: Signal<boolean>;
  readonly error: Signal<ProblemDetails | null>;
}

/** A read handle's parts with the kept read covering them; `kept` is `null` for a read nothing keeps. */
export interface KeptValueParts<A, V> extends ValueParts<A, V> {
  readonly kept: KeptGate | null;
}

/**
 * *parts* of a single-result, list or bytes read covered by the kept *read* (module comment):
 * *empty* is what the read shows holding no value (a stale report shows it). The arguments a
 * load takes are the route's client arguments.
 */
export function keptValue<A extends object, V>(
  parts: ValueParts<A, V>,
  read: KeptRead,
  empty: V,
  codec: KeptCodec<V>,
): KeptValueParts<A, V> & { readonly copies: KeptCopies<V> } {
  const copies = new KeptCopies<V>(read, codec);
  let wanted: { readonly args: A } | null = null;
  let sentKey: string | null = null;
  const settled = (): KeptSettled<V> => ({
    problem: untracked(parts.error),
    answered: untracked(parts.isLoaded),
    copy: () => untracked(parts.value),
  });
  const send = (load: boolean, args: A): Promise<void> => {
    const clientArgs = args as Readonly<Record<string, unknown>>;
    return copies.request(load, clientArgs, () => {
      sentKey = copies.key(clientArgs);
      return load ? parts.load(args) : parts.refresh();
    }, settled);
  };
  return {
    load: (args) => {
      wanted = { args };
      return send(true, args);
    },
    refresh: () => {
      if (wanted === null) {
        throw new Error(`${read.route.route}: refresh() before the first load; a view refreshes a binding only once it has loaded.`);
      }
      const { args } = wanted;
      // A copy served offline stood in for arguments never sent: asking again loads them.
      return send(sentKey !== copies.key(args as Readonly<Record<string, unknown>>), args);
    },
    isLoaded: computed(() => {
      const shown = copies.shown();
      return shown === 'kept' || (shown === 'live' && parts.isLoaded());
    }),
    value: computed(() => {
      const shown = copies.shown();
      const kept = copies.copy();
      if (shown === 'kept' && kept !== null) {
        return kept.copy;
      }
      return shown === 'stale' ? empty : parts.value();
    }),
    isLoading: parts.isLoading,
    error: computed(() => (copies.shown() === 'live' ? parts.error() : copies.problem())),
    kept: copies.gate,
    copies,
  };
}
